import React, { useState, useCallback } from 'react'
import s from './HW11.module.css'
import s2 from '../../s1-main/App.module.css'
import { restoreState } from '../hw06/localStorage/localStorage'
import SuperRange from './common/c7-SuperRange/SuperRange'

/*
* 1 - передать значения в оба слайдера
* 2 - дописать типы и логику функции change
* 3 - сделать стили в соответствии с дизайном
* */

// Тип для значения слайдера (одинарный - number, двойной - number[])
type SliderValue = number | number[];

function HW11() {
    // for autotests // не менять
    const [value1, setValue1] = useState(restoreState<number>('hw11-value1', 0))
    const [value2, setValue2] = useState(restoreState<number>('hw11-value2', 100))

    // 2. Дописываем типы и логику функции change
    const change = useCallback((event: Event, value: SliderValue) => {

        // Если пришло число (от одинарного слайдера)
        if (typeof value === 'number') {
            setValue1(value)
        }
        // Если пришёл массив [min, max] (от двойного слайдера)
        else if (Array.isArray(value) && value.length === 2) {
            // 1. Сохраняем значения в оба useState
            setValue1(value[0])
            setValue2(value[1])
        }
    }, [])

    const minRange = 0;
    const maxRange = 100;

    return (
        <div id={'hw11'}>
            <div className={s2.hwTitle}>Homework #11</div>

            <div className={s2.hw}>
                <div className={s.container}>
                    <div className={s.wrapper}>
                        <span id={'hw11-value'} className={s.number}>{value1}</span>
                        <SuperRange
                            id={'hw11-single-slider'}
                            // 1. Передаем value1 и функцию change
                            value={value1}
                            onChange={change}
                            min={minRange}
                            max={maxRange}
                        />
                    </div>
                    <div className={s.wrapper}>
                        <span id={'hw11-value-1'} className={s.number}>{value1}</span>
                        <SuperRange
                            id={'hw11-double-slider'}
                            // 1. Передаем массив [value1, value2] и функцию change
                            value={[value1, value2]}
                            onChange={change}
                            min={minRange}
                            max={maxRange}
                            step={1}
                        />
                        <span id={'hw11-value-2'} className={s.number}>{value2}</span>
                    </div>
                </div>
            </div>
        </div>
    )
}

export default HW11