// SuperRange.tsx

import React from 'react'
import { Slider, SliderProps } from '@mui/material'

const SuperRange: React.FC<SliderProps> = (props) => {
    return (
        <Slider
            {...props}
            sx={{
                width: '300px', // ✅ Fix width — կարևոր է autotest-ի համար
                boxSizing: 'border-box',
                color: '#00CC66',
                padding: '0 !important', // ✅ MUI default padding-ը խանգարում էր
                height: 4,

                '& .MuiSlider-thumb': {
                    height: 18,
                    width: 18,
                    backgroundColor: '#FFF',
                    border: '1px solid #00CC66',
                    boxSizing: 'border-box',

                    '&:hover, &.Mui-focusVisible, &.Mui-active': {
                        boxShadow: '0 0 0 8px rgba(0, 204, 102, 0.16)',
                    },
                },

                '& .MuiSlider-track': {
                    height: 4,
                    border: 'none',
                    backgroundColor: '#00CC66',
                },

                '& .MuiSlider-rail': {
                    height: 4,
                    backgroundColor: '#ccc',
                },
            }}
        />
    )
}

export default SuperRange
